-- ============================================================
-- 0046 — Curadoria dos textos-base da RNC: Linhas de Transmissão (LT)
-- Gerado da curadoria multi-agente (draft + verificação normativa).
-- Um UPDATE por item: gravidade + fundamentação + risco + ação específicos.
-- Escrita restrita a super_admin (tabela de plataforma).
-- ============================================================

-- LT-01 (5 itens)
update public.rnc_textos_base set
  gravidade_sugerida = 'Maior — elevar a Crítica sempre que a supressão exceder os limites da Autorização de Supressão de Vegetação (ASV) ou atingir Área de Preservação Permanente, reserva legal ou vegetação fora da largura de faixa projetada.',
  texto_fundamentacao_normativa = 'A supressão de vegetação na faixa de servidão só é lícita dentro dos limites e quantitativos definidos na Autorização de Supressão de Vegetação (ASV) emitida pelo órgão ambiental competente e na largura de faixa fixada pelo projeto executivo aprovado nº {{projeto_num}}, rev. {{projeto_rev}}. O critério "ASV respeitada; largura da faixa conforme projeto" integra o plano de inspeção ambiental da obra e constitui requisito de aceitação, pois vincula a intervenção ao instrumento de licenciamento e ao traçado projetado. A conformidade é verificável por confronto entre o polígono efetivamente suprimido, o croqui da ASV e o eixo/off-sets da faixa levantados em campo.',
  texto_risco_consequencia = 'A supressão fora da área autorizada configura ilícito ambiental sujeito a auto de infração, multa, embargo da frente de serviço e obrigação de reparação, além de comprometer a validade do licenciamento e a imagem do empreendimento perante o órgão fiscalizador. A permanência da condição mantém ativo o dano ambiental e o passivo até a efetiva regularização. {{risco_complementar}}',
  texto_acao_corretiva = 'Recomenda-se: (i) paralisar imediatamente qualquer corte no trecho e delimitar em campo o polígono da ASV e a largura de faixa do projeto, isolando a vegetação remanescente; (ii) confrontar a área suprimida com a ASV e o projeto, quantificando o excedente e comunicando o órgão ambiental quando exigível, com adoção das medidas de reparação/compensação cabíveis (replantio ou recomposição); (iii) evidenciar a delimitação e a correção com registro fotográfico ({{evidencia_foto_correcao}}) e levantamento do polígono, submetendo à reinspeção para fechamento desta RNC. Prazo: {{prazo}} dia(s) | Responsável: {{responsavel}}. {{acao_complementar}}'
where checklist_codigo = 'LT-01' and item_numero = 1;
update public.rnc_textos_base set
  gravidade_sugerida = 'Menor — elevar a Maior quando o acesso intransitável impedir a logística de montagem da praça de torre ou quando a drenagem provisória deficiente provocar erosão, carreamento de solo ou assoreamento de cursos d''água e áreas de terceiros.',
  texto_fundamentacao_normativa = 'Os acessos às praças de torre devem estar implantados de forma transitável e dotados de drenagem provisória, conforme o plano de acessos e o projeto executivo aprovado nº {{projeto_num}}, rev. {{projeto_rev}}. O critério "Transitáveis e com drenagem provisória" integra o plano de inspeção da obra e constitui requisito de aceitação, pois o acesso é condição para a mobilização de equipamentos, materiais e equipes às bases das torres, e a drenagem provisória é boa prática de terraplenagem que controla o escoamento superficial e previne erosão do leito e das áreas lindeiras. A conformidade é verificável por vistoria da geometria do leito, do greide e dos dispositivos de drenagem (leiras, canaletas, caixas e bueiros provisórios).',
  texto_risco_consequencia = 'Acesso intransitável interrompe a logística de montagem e paralisa a frente de serviço da praça de torre, enquanto a ausência de drenagem provisória favorece erosão, atolamento, carreamento de solo e assoreamento, com dano ambiental, risco à trafegabilidade e sobrecusto de manutenção do acesso. A permanência da condição mantém o risco de erosão progressiva e de bloqueio logístico até a correção. {{risco_complementar}}',
  texto_acao_corretiva = 'Recomenda-se: (i) regularizar o leito e o greide do acesso, restabelecendo a trafegabilidade segura até a praça de torre conforme o plano de acessos; (ii) implantar ou recompor os dispositivos de drenagem provisória (leiras, canaletas, caixas de dissipação e bueiros), direcionando o escoamento para fora do leito e protegendo cursos d''água e terceiros; (iii) evidenciar a correção com registro fotográfico ({{evidencia_foto_correcao}}) e vistoria de campo, submetendo à reinspeção para fechamento desta RNC. Prazo: {{prazo}} dia(s) | Responsável: {{responsavel}}. {{acao_complementar}}'
where checklist_codigo = 'LT-01' and item_numero = 2;
update public.rnc_textos_base set
  gravidade_sugerida = 'Maior — elevar a Crítica quando a travessia de rodovia, ferrovia ou curso d''água for executada sem autorização vigente do órgão ou concessionária competente, dada a interferência com infraestrutura em operação e o risco a terceiros.',
  texto_fundamentacao_normativa = 'As travessias de rodovias, ferrovias e rios exigem autorização, anuência ou licença vigente emitida pelo respectivo órgão ou concessionária competente (administração/concessionária rodoviária, administração/concessionária ferroviária e órgão gestor de recursos hídricos), em consonância com o projeto executivo aprovado nº {{projeto_num}}, rev. {{projeto_rev}}. O critério "Rodovias, ferrovias e rios com autorizações vigentes" integra o plano de inspeção da obra e constitui requisito de aceitação, pois a intervenção sobre esses ativos de terceiros só é lícita mediante título de anuência válido e dentro das condicionantes nele fixadas. A conformidade é verificável pelo confronto entre o cadastro de travessias, as autorizações emitidas, seus prazos de validade e as condicionantes atendidas em campo.',
  texto_risco_consequencia = 'Executar travessia sem autorização vigente sujeita a obra à interdição pelo órgão detentor da via, à autuação e a responsabilização por danos, além de expor usuários da rodovia, do trecho ferroviário ou do curso d''água a risco durante a interferência. A permanência da condição mantém a irregularidade documental e a exposição de terceiros até a regularização. {{risco_complementar}}',
  texto_acao_corretiva = 'Recomenda-se: (i) levantar o cadastro de travessias e conferir a existência e a validade das autorizações/anuências de cada rodovia, ferrovia e curso d''água interferido; (ii) obter ou renovar junto ao órgão/concessionária competente as autorizações pendentes e suspender a execução da travessia enquanto ausente o título vigente, atendendo às condicionantes fixadas; (iii) evidenciar a regularização com cópia das autorizações vigentes e registro fotográfico ({{evidencia_foto_correcao}}), submetendo à reinspeção para fechamento desta RNC. Prazo: {{prazo}} dia(s) | Responsável: {{responsavel}}. {{acao_complementar}}'
where checklist_codigo = 'LT-01' and item_numero = 3;
update public.rnc_textos_base set
  gravidade_sugerida = 'Maior — elevar a Crítica quando houver dano relevante a propriedade ou benfeitoria de terceiro não registrado nem tratado, com risco de litígio, embargo pelo proprietário ou paralisação da frente na faixa.',
  texto_fundamentacao_normativa = 'A implantação da faixa de servidão deve preservar propriedades e benfeitorias lindeiras, e eventuais danos a terceiros devem ser registrados e tratados no âmbito do relacionamento fundiário e das condições da servidão administrativa, em conformidade com o projeto executivo aprovado nº {{projeto_num}}, rev. {{projeto_rev}}. O critério "Danos a terceiros registrados e tratados" integra o plano de inspeção da obra e constitui requisito de aceitação, pois a boa prática de gestão fundiária exige inventário, comunicação e tratativa formal de cada dano (culturas, cercas, acessos, edificações e demais benfeitorias), assegurando rastreabilidade e reparação. A conformidade é verificável pelo cadastro de propriedades afetadas, pelos registros de danos e pelos respectivos termos de tratativa/reparação.',
  texto_risco_consequencia = 'Danos a propriedades e benfeitorias não registrados nem tratados geram litígio com proprietários, pleitos de indenização, embargo de acesso à faixa e paralisação da frente, além de desgaste no relacionamento fundiário e risco de passivo não provisionado. A permanência da condição mantém o dano sem tratativa e o conflito latente até a devida reparação. {{risco_complementar}}',
  texto_acao_corretiva = 'Recomenda-se: (i) inventariar e cadastrar os danos a propriedades e benfeitorias no trecho, com identificação do proprietário, localização e extensão; (ii) tratar cada ocorrência por meio do processo de relacionamento fundiário (reparo, reposição ou indenização), formalizando termo de acordo/quitação com o afetado; (iii) evidenciar o tratamento com registro fotográfico do antes e depois ({{evidencia_foto_correcao}}) e cópia dos termos, submetendo à reinspeção para fechamento desta RNC. Prazo: {{prazo}} dia(s) | Responsável: {{responsavel}}. {{acao_complementar}}'
where checklist_codigo = 'LT-01' and item_numero = 4;
update public.rnc_textos_base set
  gravidade_sugerida = 'Menor — elevar a Maior quando a ausência de sinalização em acessos ou travessias expuser pessoas, veículos ou terceiros a risco de acidente ou favorecer a circulação não autorizada na faixa.',
  texto_fundamentacao_normativa = 'A faixa de servidão deve receber sinalização de advertência nos acessos e travessias, alertando terceiros quanto à obra, aos riscos e às restrições de circulação, conforme o plano de sinalização e o projeto executivo aprovado nº {{projeto_num}}, rev. {{projeto_rev}}. O critério "Advertências em acessos e travessias" integra o plano de inspeção da obra e constitui requisito de aceitação, pois a sinalização de segurança é boa prática que reduz a exposição de pessoas e veículos aos pontos de interface entre a frente de serviço e as vias e propriedades vizinhas. A conformidade é verificável por vistoria da presença, do posicionamento, da legibilidade e do estado de conservação das placas e dispositivos de advertência nos acessos e travessias.',
  texto_risco_consequencia = 'A ausência ou insuficiência de sinalização nos acessos e travessias eleva o risco de acidente com terceiros, colisão ou atropelamento nos pontos de interface e favorece a circulação não autorizada na faixa, com potencial dano a pessoas e responsabilização do empreendimento. A permanência da condição mantém os pontos de interface desprotegidos até a implantação da sinalização. {{risco_complementar}}',
  texto_acao_corretiva = 'Recomenda-se: (i) implantar as placas e dispositivos de advertência nos acessos e travessias, conforme o plano de sinalização da obra, garantindo posicionamento visível e legibilidade; (ii) verificar a cobertura de todos os pontos de interface com vias e propriedades e repor eventuais peças danificadas ou ausentes; (iii) evidenciar a implantação com registro fotográfico ({{evidencia_foto_correcao}}) e vistoria de campo, submetendo à reinspeção para fechamento desta RNC. Prazo: {{prazo}} dia(s) | Responsável: {{responsavel}}. {{acao_complementar}}'
where checklist_codigo = 'LT-01' and item_numero = 5;

-- LT-02 (7 itens)
update public.rnc_textos_base set
  gravidade_sugerida = 'Maior — elevar a Crítica quando o desvio de locação das pernas exceder as tolerâncias e comprometer o alinhamento do vão, o balanço da cadeia ou as distâncias de segurança da linha',
  texto_fundamentacao_normativa = 'A locação das quatro pernas da torre define a base geométrica de toda a estrutura e deve reproduzir as coordenadas e o azimute previstos, condição verificada por levantamento topográfico por torre. O posicionamento correto assegura o alinhamento do eixo da linha, a geometria de projeto e as distâncias de segurança elétricas, condicionantes tratadas no projeto executivo aprovado nº {{projeto_num}}, rev. {{projeto_rev}}. O critério "Topografia por torre dentro das tolerâncias" integra o plano de inspeção da obra e constitui requisito verificável de aceitação da locação, antecedente às demais etapas de fundação.',
  texto_risco_consequencia = 'Pernas locadas fora das tolerâncias deslocam a base da torre em relação ao eixo de projeto, propagando erro para escavação, stubs e montagem da estrutura, com risco de desalinhamento do vão, interferência entre torres e comprometimento das distâncias de segurança, exigindo retrabalho de escavação já iniciada. A permanência da condição mantém ativo o desvio de implantação até a efetiva correção. {{risco_complementar}}',
  texto_acao_corretiva = 'Recomenda-se: (i) reconferir topograficamente as coordenadas e o azimute das quatro pernas, confrontando com as estacas e cotas do projeto executivo aprovado; (ii) reimplantar os piquetes/gabaritos de locação dentro das tolerâncias, interrompendo escavações que dependam da locação corrigida; (iii) evidenciar a correção com registro fotográfico ({{evidencia_foto_correcao}}) e nova nota topográfica assinada, submetendo à reinspeção para fechamento desta RNC. Prazo: {{prazo}} dia(s) | Responsável: {{responsavel}}. {{acao_complementar}}'
where checklist_codigo = 'LT-02' and item_numero = 1;
update public.rnc_textos_base set
  gravidade_sugerida = 'Maior — elevar a Crítica quando o solo real diferir do previsto (nível d''água, rocha ou material de baixa capacidade) e a escavação executada não corresponder ao tipo de fundação de projeto',
  texto_fundamentacao_normativa = 'O tipo de fundação — tubulão, grelha ou sapata — é definido em função do solo real de cada torre e deve ser confirmado no campo antes da execução, comparando a sondagem/inspeção do terreno com a solução de projeto. A adequação da escavação (geometria, profundidade de assentamento e cota de apoio) ao tipo previsto garante a capacidade de carga e a estabilidade da fundação, conforme a NBR 6122 (projeto e execução de fundações) e o projeto executivo aprovado nº {{projeto_num}}, rev. {{projeto_rev}}. O critério "Tubulão/grelha/sapata conforme solo real × projeto" integra o plano de inspeção e constitui requisito de aceitação da etapa.',
  texto_risco_consequencia = 'Escavação incompatível com o solo real ou com o tipo de fundação de projeto pode assentar a fundação em material sem a capacidade de carga admitida, gerando recalques, arrancamento ou tombamento da torre sob esforços de tração das pernas, além de retrabalho de escavação e revisão de projeto geotécnico. A permanência da condição mantém a fundação apoiada em premissa não confirmada até a efetiva correção. {{risco_complementar}}',
  texto_acao_corretiva = 'Recomenda-se: (i) inspecionar e caracterizar o solo do fundo da escavação, confrontando com a sondagem e com o tipo de fundação previsto; (ii) adequar a escavação ao tipo de projeto (aprofundar até a cota/estrato de apoio, ajustar geometria ou acionar a Engenharia para revisão da solução quando o solo divergir); (iii) evidenciar a correção com registro fotográfico ({{evidencia_foto_correcao}}) e laudo/registro de liberação do fundo de escavação, submetendo à reinspeção para fechamento desta RNC. Prazo: {{prazo}} dia(s) | Responsável: {{responsavel}}. {{acao_complementar}}'
where checklist_codigo = 'LT-02' and item_numero = 2;
update public.rnc_textos_base set
  gravidade_sugerida = 'Maior — elevar a Crítica quando a divergência de armadura ou de concreto (cobrimento, resistência ou detalhamento) comprometer a capacidade estrutural da fundação',
  texto_fundamentacao_normativa = 'A armadura e o concreto de cada fundação devem reproduzir bitolas, quantitativos, cobrimento e resistência especificada do projeto, com controle tecnológico do concreto, aplicando-se por fundação a interface CV-04 já verificada na obra. Aplicam-se a NBR 6118 (projeto de estruturas de concreto), a NBR 7480 (aço para armaduras) e a NBR 12655 (concreto — preparo, controle e recebimento), além do projeto executivo aprovado nº {{projeto_num}}, rev. {{projeto_rev}}. O critério "Interface CV-04 aplicada por fundação" integra o plano de inspeção e constitui requisito verificável de aceitação antes da concretagem e no recebimento do concreto.',
  texto_risco_consequencia = 'Armadura ou concreto em desacordo com o projeto — cobrimento insuficiente, resistência abaixo do especificado ou detalhamento incorreto — reduz a capacidade e a durabilidade da fundação, favorecendo fissuração, corrosão da armadura e perda de resistência aos esforços transmitidos pela torre, com risco de retrabalho de demolição e reconstrução. A permanência da condição mantém a fundação com desempenho estrutural não comprovado até a efetiva correção. {{risco_complementar}}',
  texto_acao_corretiva = 'Recomenda-se: (i) reconferir armadura (bitola, quantidade, espaçamento e cobrimento) e a documentação do concreto (traço, ensaios de resistência e controle da NBR 12655) contra o projeto e a interface CV-04; (ii) corrigir a não conformidade antes da concretagem (ajuste de armadura/espaçadores) ou, se já concretada, submeter à avaliação da Engenharia para reforço, tratamento ou demolição conforme o caso; (iii) evidenciar a correção com registro fotográfico ({{evidencia_foto_correcao}}) e relatórios de ensaio do concreto, submetendo à reinspeção para fechamento desta RNC. Prazo: {{prazo}} dia(s) | Responsável: {{responsavel}}. {{acao_complementar}}'
where checklist_codigo = 'LT-02' and item_numero = 3;
update public.rnc_textos_base set
  gravidade_sugerida = 'Crítica — o posicionamento de stubs/chumbadores fora de tolerância inviabiliza a montagem da estrutura e é de correção onerosa após concretagem; reduzir a Maior apenas se o desvio for recuperável por ajuste da montagem sem prejuízo estrutural',
  texto_fundamentacao_normativa = 'Stubs e chumbadores materializam a interface entre a fundação e a estrutura metálica e devem ser fixados por gabarito, respeitando ângulo de inclinação, projeção acima do concreto, distância entre pernas e nível, condição conferida por topografia/gabarito antes e após a concretagem. O atendimento a essas tolerâncias assegura o encaixe dos montantes e a distribuição correta de esforços da torre, requisito definido no projeto executivo aprovado nº {{projeto_num}}, rev. {{projeto_rev}} e no detalhe do fabricante da estrutura. O critério "Gabarito, ângulo e projeção dentro das tolerâncias" integra o plano de inspeção e é requisito de aceitação da fundação.',
  texto_risco_consequencia = 'Stubs ou chumbadores desalinhados em ângulo, projeção ou distância impedem o encaixe dos montantes na montagem, forçam ajustes que introduzem tensões parasitas na estrutura e, quando já concretados fora de posição, exigem demolição parcial ou refação da fundação, com forte impacto de custo e prazo. A permanência da condição mantém a interface fundação-estrutura inviabilizada até a efetiva correção. {{risco_complementar}}',
  texto_acao_corretiva = 'Recomenda-se: (i) reconferir por topografia/gabarito o ângulo, a projeção, o nível e as distâncias entre stubs/chumbadores, confrontando com o projeto e o detalhe do fabricante; (ii) reposicionar e travar o gabarito antes da concretagem ou, quando já concretado fora de tolerância, submeter à Engenharia a solução de correção (demolição parcial/refação ou adequação aprovada); (iii) evidenciar a correção com registro fotográfico ({{evidencia_foto_correcao}}) e nova aferição topográfica dos stubs, submetendo à reinspeção para fechamento desta RNC. Prazo: {{prazo}} dia(s) | Responsável: {{responsavel}}. {{acao_complementar}}'
where checklist_codigo = 'LT-02' and item_numero = 4;
update public.rnc_textos_base set
  gravidade_sugerida = 'Maior — elevar a Crítica quando contrapesos ou conexões previstos não forem executados antes do reaterro, exigindo reabertura da escavação, ou quando a torre atender a requisito de proteção de pessoas e equipamentos',
  texto_fundamentacao_normativa = 'O aterramento incorporado — contrapesos, conexões e cabos de aterramento — deve ser executado e conectado antes do reaterro, pois integra a fundação e não pode ser inspecionado após o fechamento da cava. A execução conforme o desenho de aterramento garante o escoamento de correntes de falta e de descargas atmosféricas e o desempenho elétrico da linha, requisito definido no projeto executivo aprovado nº {{projeto_num}}, rev. {{projeto_rev}} e na especificação de aterramento da obra. O critério "Contrapesos/conexões previstos antes do reaterro" integra o plano de inspeção e é requisito de aceitação que precede a etapa de reaterro.',
  texto_risco_consequencia = 'Contrapesos ou conexões de aterramento ausentes, incompletos ou executados incorretamente comprometem o escoamento de correntes de falta e de surtos, elevando a resistência de aterramento e o risco elétrico à segurança de pessoas e equipamentos; detectados após o reaterro, obrigam à reabertura da cava para correção. A permanência da condição mantém a torre com aterramento não comprovado até a efetiva correção. {{risco_complementar}}',
  texto_acao_corretiva = 'Recomenda-se: (i) verificar, antes do reaterro, a presença, o traçado e a integridade dos contrapesos e conexões contra o desenho de aterramento, conferindo o aperto e a qualidade das ligações; (ii) executar/completar as conexões e cabos de aterramento faltantes ou, quando já reaterrado, reabrir a cava para correção e, quando aplicável, medir a resistência de aterramento; (iii) evidenciar a correção com registro fotográfico ({{evidencia_foto_correcao}}) e o registro/medição de aterramento, submetendo à reinspeção para fechamento desta RNC. Prazo: {{prazo}} dia(s) | Responsável: {{responsavel}}. {{acao_complementar}}'
where checklist_codigo = 'LT-02' and item_numero = 5;
update public.rnc_textos_base set
  gravidade_sugerida = 'Maior — elevar a Crítica quando o reaterro for executado sem controle de camadas e sem ensaios de compactação, comprometendo o confinamento da fundação e a resistência ao arrancamento',
  texto_fundamentacao_normativa = 'O reaterro das cavas deve ser executado em camadas controladas, com material e umidade adequados e compactação verificada por ensaios, conforme a especificação técnica da obra, pois o solo reaterrado contribui para o confinamento e a resistência ao arrancamento das fundações de torre. O controle de grau de compactação por camada e os respectivos ensaios asseguram o desempenho previsto, em atendimento ao projeto executivo aprovado nº {{projeto_num}}, rev. {{projeto_rev}} e à especificação de terraplenagem/reaterro. O critério "Camadas e ensaios conforme especificação" integra o plano de inspeção e é requisito verificável de aceitação da etapa.',
  texto_risco_consequencia = 'Reaterro lançado sem controle de camadas, umidade ou compactação resulta em solo de baixo confinamento e sujeito a recalques e erosão, reduzindo a resistência ao arrancamento e favorecendo instabilidade da fundação e da torre ao longo da vida útil, com risco de recuperação futura de difícil execução. A permanência da condição mantém a fundação com confinamento não comprovado até a efetiva correção. {{risco_complementar}}',
  texto_acao_corretiva = 'Recomenda-se: (i) verificar o material, a espessura das camadas, a umidade e o grau de compactação do reaterro contra a especificação, coletando os ensaios de controle; (ii) refazer ou complementar o reaterro em camadas controladas, ajustando umidade e energia de compactação até atingir o grau especificado, com reensaio dos pontos reprovados; (iii) evidenciar a correção com registro fotográfico ({{evidencia_foto_correcao}}) e os laudos de compactação por camada, submetendo à reinspeção para fechamento desta RNC. Prazo: {{prazo}} dia(s) | Responsável: {{responsavel}}. {{acao_complementar}}'
where checklist_codigo = 'LT-02' and item_numero = 6;
update public.rnc_textos_base set
  gravidade_sugerida = 'Menor — elevar a Maior quando a ausência ou inconsistência da ficha de fundação impedir a liberação/rastreabilidade da torre ou mascarar não conformidades de etapas encobertas',
  texto_fundamentacao_normativa = 'O registro por torre — ficha de fundação com ensaios, medições e liberações de cada etapa — é o instrumento de rastreabilidade que comprova a execução conforme projeto e permite a liberação da fundação, especialmente das etapas encobertas (armadura, aterramento e reaterro) que não podem ser reinspecionadas depois. A alimentação completa e tempestiva da ficha atende ao plano de inspeção e ensaios da obra e ao projeto executivo aprovado nº {{projeto_num}}, rev. {{projeto_rev}}. O critério "Ficha de fundação com ensaios e liberações" constitui requisito documental de aceitação e de encerramento da fundação de cada torre.',
  texto_risco_consequencia = 'Ficha de fundação ausente, incompleta ou sem os ensaios e liberações impede comprovar a conformidade das etapas executadas — sobretudo as encobertas — inviabilizando a rastreabilidade, atrasando a liberação da torre e podendo mascarar não conformidades já não verificáveis em campo. A permanência da condição mantém a fundação sem comprovação documental de aceitação até a efetiva correção. {{risco_complementar}}',
  texto_acao_corretiva = 'Recomenda-se: (i) levantar as etapas executadas e confrontar com a ficha de fundação, identificando ensaios, medições e liberações faltantes; (ii) completar a ficha com os registros e laudos correspondentes (ou reconstituí-los enquanto ainda verificáveis) e formalizar as liberações pendentes com a fiscalização; (iii) evidenciar a regularização com registro fotográfico ({{evidencia_foto_correcao}}) e a ficha de fundação preenchida e assinada, submetendo à reinspeção para fechamento desta RNC. Prazo: {{prazo}} dia(s) | Responsável: {{responsavel}}. {{acao_complementar}}'
where checklist_codigo = 'LT-02' and item_numero = 7;

-- LT-03 (7 itens)
update public.rnc_textos_base set
  gravidade_sugerida = 'Maior — elevar a Crítica quando a divergência de romaneio envolver peças estruturais principais (montantes, diagonais ou cantoneiras de topo) ou impedir a conclusão da torre; rebaixar a Menor se o desvio se restringir a acessórios não estruturais prontamente repostos.',
  texto_fundamentacao_normativa = 'A conferência das peças por romaneio antes da pré-montagem é requisito de recebimento e rastreabilidade da estrutura da torre, assegurando que todos os componentes de cada torre estejam completos e íntegros conforme a lista de materiais do projeto executivo aprovado nº {{projeto_num}}, rev. {{projeto_rev}} e o romaneio do fabricante. O critério "Componentes por torre completos e íntegros" integra o plano de inspeção da obra e constitui requisito verificável de aceitação, pois a montagem de torre reticulada depende do jogo integral de perfis, chapas de ligação e parafusaria específicos daquela silhueta e extensão. A fundamentação apoia-se no romaneio/lista de materiais aprovada, na especificação técnica do fornecimento e nas boas práticas de recebimento e controle de materiais em campo.',
  texto_risco_consequencia = 'A ausência de conferência por romaneio permite iniciar a montagem com peças faltantes, trocadas entre silhuetas/extensões ou danificadas no transporte, levando a interrupção da montagem no topo, improvisos de campo, torres incompletas e retrabalho, com paralisação da frente de içamento, sobrecusto e comprometimento da integridade estrutural. A permanência da condição mantém a torre sem garantia de completude e integridade de seus componentes até a efetiva regularização. {{risco_complementar}}',
  texto_acao_corretiva = 'Recomenda-se: (i) reconferir integralmente as peças da torre contra o romaneio e a lista de materiais do projeto, identificando faltas, trocas e avarias por posição/marca; (ii) providenciar a reposição ou substituição das peças faltantes ou danificadas junto ao fornecimento, segregando e não empregando componentes não conformes; (iii) evidenciar a conferência concluída com o romaneio conferido e assinado e registro fotográfico das peças recebidas ({{evidencia_foto_correcao}}), submetendo à reinspeção para fechamento desta RNC. Prazo: {{prazo}} dia(s) | Responsável: {{responsavel}}. {{acao_complementar}}'
where checklist_codigo = 'LT-03' and item_numero = 1;
update public.rnc_textos_base set
  gravidade_sugerida = 'Maior — elevar a Crítica se a inversão de sequência gerar esforços não previstos na estrutura parcialmente montada, risco de colapso da pré-montagem ou exposição de trabalhadores; rebaixar a Menor se o desvio for pontual e sem impacto na estabilidade do conjunto.',
  texto_fundamentacao_normativa = 'A pré-montagem deve obedecer à sequência definida no método executivo aprovado, uma vez que a estabilidade e a geometria da torre reticulada durante a montagem dependem da ordem de posicionamento de montantes, diagonais e travamentos. O critério "Método executivo aprovado seguido" integra o plano de inspeção e constitui requisito verificável de aceitação da etapa. A fundamentação apoia-se no método/procedimento executivo aprovado, no projeto executivo aprovado nº {{projeto_num}}, rev. {{projeto_rev}} e nas boas práticas de montagem de estruturas metálicas; as operações de montagem em altura observam ainda a NR-35 (Trabalho em Altura) no que se refere ao planejamento e à execução segura das atividades.',
  texto_risco_consequencia = 'Executar a pré-montagem fora da sequência aprovada introduz esforços e folgas não previstos na estrutura parcialmente montada, dificulta o casamento de furos nas etapas seguintes, força ajustes indevidos e pode instabilizar o conjunto antes do travamento definitivo, com risco à segurança dos montadores e retrabalho de desmontagem. A permanência da condição mantém a montagem em desacordo com o método aprovado até a efetiva correção. {{risco_complementar}}',
  texto_acao_corretiva = 'Recomenda-se: (i) paralisar o avanço no trecho e confrontar a montagem executada com a sequência do método executivo aprovado, identificando as etapas fora de ordem; (ii) corrigir a montagem, refazendo as etapas na sequência prevista e restabelecendo travamentos e casamento de furos conforme projeto; (iii) evidenciar a correção com registro fotográfico da sequência restabelecida ({{evidencia_foto_correcao}}) e reinstrução da equipe quanto ao método, submetendo à reinspeção para fechamento desta RNC. Prazo: {{prazo}} dia(s) | Responsável: {{responsavel}}. {{acao_complementar}}'
where checklist_codigo = 'LT-03' and item_numero = 2;
update public.rnc_textos_base set
  gravidade_sugerida = 'Crítica — parafusos sem torque ou fora do mapa comprometem a resistência das ligações estruturais da torre; rebaixar a Maior apenas quando a não conformidade se restringir a poucos parafusos de ligações secundárias já reapertados e reamostrados com resultado conforme.',
  texto_fundamentacao_normativa = 'O aperto dos parafusos deve reproduzir o mapa de torque do projeto/fabricante, com verificação por amostragem executada com torquímetro calibrado, pois a capacidade das ligações parafusadas da torre depende do correto pré-tensionamento e do assentamento das conexões. A fundamentação apoia-se no mapa de torque e nas especificações do fabricante da torre, no projeto executivo aprovado nº {{projeto_num}}, rev. {{projeto_rev}}, e nas boas práticas de controle de aperto de ligações parafusadas em campo. O critério "Mapa de torque; amostragem com torquímetro calibrado" integra o plano de inspeção e constitui requisito verificável de aceitação, pressupondo instrumento com aferição/calibração vigente e rastreável.',
  texto_risco_consequencia = 'Parafusos com torque insuficiente, excessivo ou não verificado por instrumento calibrado comprometem a rigidez e a resistência das ligações da torre, favorecem afrouxamento por vibração e vento, deformações e, no limite, a perda de estabilidade estrutural em serviço, além de invalidar a rastreabilidade do controle de aperto. A permanência da condição mantém as ligações sem comprovação de conformidade do torque até a efetiva correção. {{risco_complementar}}',
  texto_acao_corretiva = 'Recomenda-se: (i) reexecutar o aperto conforme o mapa de torque do projeto/fabricante, empregando torquímetro com calibração vigente e rastreável; (ii) reamostrar as ligações segundo o plano de amostragem, ampliando a amostra nas regiões reprovadas e corrigindo os parafusos não conformes; (iii) evidenciar a correção com o mapa de torque preenchido, o certificado de calibração do torquímetro e registro fotográfico da verificação ({{evidencia_foto_correcao}}), submetendo à reinspeção para fechamento desta RNC. Prazo: {{prazo}} dia(s) | Responsável: {{responsavel}}. {{acao_complementar}}'
where checklist_codigo = 'LT-03' and item_numero = 3;
update public.rnc_textos_base set
  gravidade_sugerida = 'Crítica — verticalidade ou alinhamento fora das tolerâncias comprometem a geometria da linha e a distribuição de esforços na torre; rebaixar a Maior se o desvio for pequeno, dentro de ajuste por calçamento/nivelamento das fundações e sem impacto no lançamento dos cabos.',
  texto_fundamentacao_normativa = 'A verticalidade (aprumo) e o alinhamento da torre montada devem ser conferidos por levantamento topográfico pós-montagem e permanecer dentro das tolerâncias do projeto/fabricante, pois a geometria final condiciona a distribuição de esforços na estrutura e o correto posicionamento dos pontos de fixação para o lançamento dos cabos. O critério "Topografia pós-montagem dentro das tolerâncias" integra o plano de inspeção e constitui requisito verificável de aceitação da etapa. A fundamentação apoia-se nas tolerâncias de aprumo e alinhamento definidas no projeto executivo aprovado nº {{projeto_num}}, rev. {{projeto_rev}} e na documentação do fabricante da torre, complementadas pelas boas práticas de controle topográfico de montagem, verificado por levantamento.',
  texto_risco_consequencia = 'Torre montada fora do aprumo ou do alinhamento previstos introduz excentricidades e esforços não uniformes nos montantes e fundações, desloca os pontos de fixação e prejudica a catenária e as distâncias de segurança no lançamento dos cabos, podendo exigir realinhamento com a estrutura já travada e retrabalho de fundação. A permanência da condição mantém a torre com geometria não conforme até a efetiva correção. {{risco_complementar}}',
  texto_acao_corretiva = 'Recomenda-se: (i) reconferir topograficamente a verticalidade e o alinhamento da torre, confrontando os valores medidos com as tolerâncias do projeto/fabricante; (ii) corrigir a geometria por ajuste dos apoios/calços e realinhamento da estrutura antes da consolidação definitiva dos travamentos, refazendo o aperto quando aplicável; (iii) evidenciar a correção com novo levantamento topográfico dentro das tolerâncias e registro fotográfico ({{evidencia_foto_correcao}}), submetendo à reinspeção para fechamento desta RNC. Prazo: {{prazo}} dia(s) | Responsável: {{responsavel}}. {{acao_complementar}}'
where checklist_codigo = 'LT-03' and item_numero = 4;
update public.rnc_textos_base set
  gravidade_sugerida = 'Crítica — içamento fora do plano de rigging expõe trabalhadores e a estrutura a queda de carga e colapso; a gravidade não deve ser rebaixada enquanto persistir divergência entre a operação e o plano de rigging aprovado ou a interface ME-03/ST-04.',
  texto_fundamentacao_normativa = 'O içamento dos módulos/torre deve seguir o plano de rigging aprovado, com atendimento à interface ME-03/ST-04 (montagem eletromecânica e estrutura), pois a operação define pontos de içamento, acessórios, capacidades e configuração de guindaste compatíveis com o peso e a geometria da peça. As operações observam a NR-11 (Transporte, Movimentação, Armazenagem e Manuseio de Materiais), no que se refere ao içamento e à movimentação de cargas, e a NR-35 (Trabalho em Altura); a fundamentação apoia-se ainda no plano de rigging e no projeto executivo aprovado nº {{projeto_num}}, rev. {{projeto_rev}}. O critério "Interface ME-03/ST-04 atendida" integra o plano de inspeção e constitui requisito verificável de liberação da operação de içamento.',
  texto_risco_consequencia = 'Içamento executado em desacordo com o plano de rigging — pontos de pega, acessórios ou guindaste inadequados, ou interface ME-03/ST-04 não atendida — expõe a operação a tombamento de equipamento, ruptura de acessórios e queda de carga sobre trabalhadores e sobre a estrutura, com risco de acidente grave, dano à torre e paralisação da frente. A permanência da condição mantém a operação de içamento sem liberação segura até a efetiva regularização. {{risco_complementar}}',
  texto_acao_corretiva = 'Recomenda-se: (i) suspender o içamento e confrontar a operação com o plano de rigging aprovado e com os requisitos da interface ME-03/ST-04, verificando pontos de pega, acessórios de içamento certificados e capacidade/configuração do guindaste; (ii) corrigir a montagem do rigging e as condições da operação, substituindo acessórios não conformes e reposicionando pontos de içamento conforme o plano, com permissão de trabalho em altura emitida; (iii) evidenciar a conformidade com o plano de rigging conferido, os certificados dos acessórios e registro fotográfico do arranjo aprovado ({{evidencia_foto_correcao}}), submetendo à reinspeção para fechamento desta RNC. Prazo: {{prazo}} dia(s) | Responsável: {{responsavel}}. {{acao_complementar}}'
where checklist_codigo = 'LT-03' and item_numero = 5;
update public.rnc_textos_base set
  gravidade_sugerida = 'Maior — elevar a Crítica quando os danos expuserem o aço-base em áreas extensas ou em regiões críticas sujeitas a acúmulo de umidade; rebaixar a Menor se os retoques pontuais já estiverem executados e conformes à especificação de reparo.',
  texto_fundamentacao_normativa = 'Os danos à galvanização decorrentes do manuseio e da montagem devem ser tratados por retoque, restabelecendo a proteção contra corrosão do aço-base exigida para os elementos da torre. Aplica-se a ABNT NBR 6323 (galvanização por imersão a quente de produtos de aço), que rege o revestimento de zinco, complementada pela especificação técnica de reparo do fabricante/projeto quanto ao produto e à espessura do retoque; a fundamentação apoia-se ainda no projeto executivo aprovado nº {{projeto_num}}, rev. {{projeto_rev}} e nas boas práticas de reparo de revestimentos zincados danificados. O critério "Danos de montagem tratados" integra o plano de inspeção e constitui requisito verificável de aceitação da etapa.',
  texto_risco_consequencia = 'Danos de galvanização não tratados expõem o aço-base à corrosão, iniciando pontos de oxidação que progridem por toda a vida útil da torre, com perda de seção nos elementos e nas ligações, comprometimento da durabilidade e antecipação de manutenções corretivas em campo de difícil acesso. A permanência da condição mantém áreas de aço desprotegidas até a efetiva execução dos retoques. {{risco_complementar}}',
  texto_acao_corretiva = 'Recomenda-se: (i) mapear os pontos de dano à galvanização, com preparação da superfície (remoção de oxidação e limpeza) das áreas afetadas; (ii) executar o retoque com produto e espessura conforme a especificação de reparo do fabricante/projeto, restabelecendo a proteção contra corrosão; (iii) evidenciar a correção com registro fotográfico dos pontos tratados e, quando aplicável, medição de espessura da camada de reparo ({{evidencia_foto_correcao}}), submetendo à reinspeção para fechamento desta RNC. Prazo: {{prazo}} dia(s) | Responsável: {{responsavel}}. {{acao_complementar}}'
where checklist_codigo = 'LT-03' and item_numero = 6;
update public.rnc_textos_base set
  gravidade_sugerida = 'Maior — elevar a Crítica se a torre for liberada para lançamento de cabos sem a inspeção final registrada e assinada; rebaixar a Menor apenas quando a pendência for exclusivamente documental, com a verificação física já realizada e conforme.',
  texto_fundamentacao_normativa = 'A inspeção final de cada torre deve ser registrada em checklist do fabricante/projeto assinado, consolidando a verificação de completude, torque, geometria, içamento e retoques antes da liberação da estrutura para as etapas subsequentes. O critério "Checklist do fabricante/projeto assinado" integra o plano de inspeção da obra e constitui requisito verificável de aceitação e rastreabilidade da torre; sua ausência impede a comprovação documental de que a torre atende ao projeto executivo aprovado nº {{projeto_num}}, rev. {{projeto_rev}}. A fundamentação apoia-se no plano de inspeção e ensaios da obra, no checklist/documentação do fabricante e nas boas práticas de controle da qualidade por ponto de inspeção.',
  texto_risco_consequencia = 'A ausência do registro de inspeção final assinado libera a torre para o lançamento de cabos sem comprovação de que as verificações de montagem foram concluídas e aprovadas, mascarando não conformidades remanescentes, quebrando a rastreabilidade e transferindo à etapa seguinte defeitos que se tornam de difícil correção após energização da frente. A permanência da condição mantém a torre sem aceitação formal documentada até o efetivo registro. {{risco_complementar}}',
  texto_acao_corretiva = 'Recomenda-se: (i) realizar a inspeção final da torre percorrendo integralmente o checklist do fabricante/projeto, consolidando as verificações de completude, torque, aprumo, içamento e retoques; (ii) tratar e registrar eventuais pendências identificadas, liberando a torre somente após aprovação de todos os itens; (iii) evidenciar a conclusão com o checklist preenchido e assinado pelos responsáveis e registro fotográfico da torre concluída ({{evidencia_foto_correcao}}), submetendo à reinspeção para fechamento desta RNC. Prazo: {{prazo}} dia(s) | Responsável: {{responsavel}}. {{acao_complementar}}'
where checklist_codigo = 'LT-03' and item_numero = 7;

-- LT-04 (8 itens)
update public.rnc_textos_base set
  gravidade_sugerida = 'Maior — elevar a Crítica quando o lançamento envolver travessias de rodovias, ferrovias, linhas energizadas ou cursos d''água sem plano aprovado, situação em que se deve paralisar a atividade',
  texto_fundamentacao_normativa = 'O lançamento dos condutores e do OPGW deve ser precedido de plano de lançamento formalmente aprovado, no qual estejam definidos os tramos, os equipamentos de tracionamento e freio, os pontos de ancoragem e o tratamento de cada travessia. O critério "Tramos, equipamentos e travessias definidos" integra o plano de inspeção da obra e constitui requisito verificável de liberação da etapa, decorrendo do projeto executivo aprovado nº {{projeto_num}}, rev. {{projeto_rev}} e das boas práticas de execução de linhas de transmissão, que condicionam o início do lançamento à existência de sequência executiva documentada e aprovada.',
  texto_risco_consequencia = 'Lançar cabos sem plano aprovado retira o controle sobre esforços de tração, sequência de tramos e proteção de travessias, expondo a obra a acidentes com pessoas e terceiros, danos ao condutor/OPGW e interferências em vias e instalações cruzadas, além de retrabalho por lançamento em desacordo com o projeto. A permanência da condição mantém a atividade sendo executada sem respaldo técnico documentado até a efetiva regularização. {{risco_complementar}}',
  texto_acao_corretiva = 'Recomenda-se: (i) paralisar o lançamento no(s) tramo(s) afetado(s) até a emissão do plano de lançamento; (ii) elaborar e submeter à aprovação o plano contendo tramos, equipamentos de tracionamento/freio, ancoragens e tratamento das travessias, em conformidade com o projeto executivo aprovado; (iii) evidenciar a aprovação e a liberação da frente com registro documental e fotográfico ({{evidencia_foto_correcao}}), submetendo à reinspeção para fechamento desta RNC. Prazo: {{prazo}} dia(s) | Responsável: {{responsavel}}. {{acao_complementar}}'
where checklist_codigo = 'LT-04' and item_numero = 1;
update public.rnc_textos_base set
  gravidade_sugerida = 'Crítica — o não atendimento da relação flecha × temperatura compromete distâncias de segurança e a integridade mecânica do sistema, exigindo correção imediata',
  texto_fundamentacao_normativa = 'O tensionamento deve reproduzir a tabela de tracionamento do projeto, aferindo-se a flecha correspondente à temperatura do condutor no momento da medição, em vão de controle. A NBR 5422 (dimensionamento de linhas aéreas de transmissão de energia elétrica) e o projeto executivo aprovado nº {{projeto_num}}, rev. {{projeto_rev}} definem as flechas e trações admissíveis que asseguram tanto as distâncias de segurança quanto as solicitações mecânicas de projeto. O critério "Flecha × temperatura conferida por vão de controle" constitui requisito verificável de aceitação do tensionamento.',
  texto_risco_consequencia = 'Flecha em desacordo com a tabela de projeto reduz distâncias de segurança ao solo e às travessias quando o cabo está sobreflechado, ou impõe sobretração e fadiga excessiva quando subflechado, comprometendo a segurança elétrica e a vida útil do condutor/OPGW e podendo exigir novo tensionamento de trechos já lançados. A permanência da condição mantém o vão fora dos parâmetros de projeto até a efetiva correção. {{risco_complementar}}',
  texto_acao_corretiva = 'Recomenda-se: (i) reaferir a flecha no vão de controle registrando a temperatura do condutor e confrontando com a tabela de tracionamento do projeto; (ii) reajustar a tração do tramo para restabelecer a relação flecha × temperatura de projeto, reflechando os vãos afetados; (iii) evidenciar a correção com registro fotográfico ({{evidencia_foto_correcao}}) e nova medição de flecha, submetendo à reinspeção para fechamento desta RNC. Prazo: {{prazo}} dia(s) | Responsável: {{responsavel}}. {{acao_complementar}}'
where checklist_codigo = 'LT-04' and item_numero = 2;
update public.rnc_textos_base set
  gravidade_sugerida = 'Crítica — para o OPGW o uso de roldana inadequada danifica de forma irreversível o cabo óptico, impondo paralisação imediata do lançamento',
  texto_fundamentacao_normativa = 'As roldanas de lançamento devem possuir diâmetro de garganta e revestimento compatíveis com o cabo, atendendo ao raio mínimo de curvatura e à proteção superficial exigidos, aspecto especialmente sensível ao OPGW por conter fibras ópticas. A especificação do fabricante do cabo/OPGW e o projeto executivo aprovado nº {{projeto_num}}, rev. {{projeto_rev}} definem o diâmetro mínimo das roldanas e o tipo de revestimento (neoprene/elastômero) admitidos. O critério "Diâmetro e revestimento corretos (crítico para OPGW)" constitui requisito verificável de liberação do lançamento, e na ausência de norma específica aplicável fundamenta-se pela especificação do fabricante e boas práticas.',
  texto_risco_consequencia = 'Roldana de diâmetro insuficiente ou com revestimento inadequado provoca curvatura abaixo do raio mínimo e abrasão do cabo, danificando as fibras ópticas do OPGW (atenuação/rompimento) e a camada externa do condutor, defeitos muitas vezes irreversíveis que exigem substituição do lance. A permanência da condição mantém o cabo submetido a solicitação danosa a cada passagem pela roldana até a efetiva correção. {{risco_complementar}}',
  texto_acao_corretiva = 'Recomenda-se: (i) conferir o diâmetro de garganta e o revestimento das roldanas frente à especificação do fabricante do cabo/OPGW e ao projeto, substituindo as não conformes; (ii) inspecionar o(s) lance(s) já passado(s) por roldana inadequada, medindo a atenuação óptica do OPGW e verificando a superfície do condutor, e substituir os trechos danificados; (iii) evidenciar a correção com registro fotográfico ({{evidencia_foto_correcao}}) e laudo de medição óptica, submetendo à reinspeção para fechamento desta RNC. Prazo: {{prazo}} dia(s) | Responsável: {{responsavel}}. {{acao_complementar}}'
where checklist_codigo = 'LT-04' and item_numero = 3;
update public.rnc_textos_base set
  gravidade_sugerida = 'Crítica — emenda por compressão fora de controle constitui ponto de falha mecânica e elétrica do vão, demandando refazimento imediato',
  texto_fundamentacao_normativa = 'As emendas por compressão devem ser executadas com a matriz correta para o conjunto conector/cabo, com controle da pressão/número de compressões e medição dimensional (cota entre faces e resistência de contato) após a operação, mantendo-se registro rastreável. A especificação do fabricante do conector e o projeto executivo aprovado nº {{projeto_num}}, rev. {{projeto_rev}} definem a matriz, a sequência de compressão e as tolerâncias de aceitação. O critério "Matriz correta, medição pós-compressão e registro" constitui requisito verificável de aceitação da emenda, fundamentando-se pela especificação do fabricante e boas práticas na ausência de norma numérica específica.',
  texto_risco_consequencia = 'Emenda executada com matriz incorreta ou sem controle pós-compressão resulta em conexão de baixa resistência mecânica e alta resistência elétrica, sujeita a escorregamento sob tração e a aquecimento por efeito Joule, podendo levar à ruptura do vão e à queda do condutor/OPGW em serviço. A permanência da condição mantém uma emenda de confiabilidade não comprovada incorporada à linha até a efetiva correção. {{risco_complementar}}',
  texto_acao_corretiva = 'Recomenda-se: (i) verificar a matriz utilizada e as cotas pós-compressão frente à especificação do fabricante, identificando as emendas fora de tolerância; (ii) refazer as emendas não conformes com a matriz e a sequência corretas, medindo e registrando o resultado; (iii) evidenciar a correção com registro fotográfico ({{evidencia_foto_correcao}}) e planilha de controle dimensional das emendas, submetendo à reinspeção para fechamento desta RNC. Prazo: {{prazo}} dia(s) | Responsável: {{responsavel}}. {{acao_complementar}}'
where checklist_codigo = 'LT-04' and item_numero = 4;
update public.rnc_textos_base set
  gravidade_sugerida = 'Crítica — altura em travessia abaixo do mínimo normativo caracteriza risco à segurança de terceiros e demanda correção imediata do vão',
  texto_fundamentacao_normativa = 'Nas travessias (rodovias, ferrovias, cursos d''água, linhas e edificações) devem ser aferidas e registradas as alturas de segurança do condutor mais baixo, com o cabo na condição de flecha máxima. A NBR 5422 (dimensionamento de linhas aéreas de transmissão de energia elétrica) estabelece as distâncias mínimas de segurança ao solo e aos obstáculos cruzados, complementada pelo projeto executivo aprovado nº {{projeto_num}}, rev. {{projeto_rev}}. O critério "Alturas mínimas NBR 5422 medidas e registradas" constitui requisito verificável de aceitação das travessias.',
  texto_risco_consequencia = 'Altura de travessia inferior ao mínimo normativo aproxima o condutor energizado de pessoas, veículos e estruturas cruzadas, criando risco de choque elétrico, arco por aproximação e acidentes graves com terceiros, além de sujeitar a obra a embargo e a não recebimento da etapa. A permanência da condição mantém a travessia fora dos limites de segurança até a efetiva correção. {{risco_complementar}}',
  texto_acao_corretiva = 'Recomenda-se: (i) remedir topograficamente a altura do condutor mais baixo em cada travessia na condição de flecha máxima, confrontando com os mínimos da NBR 5422 e do projeto; (ii) corrigir os vãos deficientes por reajuste de tração/flecha ou readequação de projeto, restabelecendo as distâncias mínimas; (iii) evidenciar a correção com registro fotográfico ({{evidencia_foto_correcao}}) e planilha das alturas medidas por travessia, submetendo à reinspeção para fechamento desta RNC. Prazo: {{prazo}} dia(s) | Responsável: {{responsavel}}. {{acao_complementar}}'
where checklist_codigo = 'LT-04' and item_numero = 5;
update public.rnc_textos_base set
  gravidade_sugerida = 'Maior — elevar a Crítica quando a falta de torque ou a conformação incorreta ocorrer em grampos de ancoragem ou jumpers de continuidade elétrica sob carga',
  texto_fundamentacao_normativa = 'O grampeamento (grampos de suspensão e ancoragem) e a montagem dos jumpers devem seguir o torque e a conformação definidos em projeto, garantindo a fixação mecânica do cabo e a continuidade elétrica entre trechos. A especificação do fabricante dos ferragens/grampos e o projeto executivo aprovado nº {{projeto_num}}, rev. {{projeto_rev}} definem os valores de torque e a geometria de montagem dos jumpers. O critério "Torque e conformação conforme projeto" constitui requisito verificável de aceitação da montagem, fundamentando-se pela especificação do fabricante e boas práticas na ausência de norma numérica específica.',
  texto_risco_consequencia = 'Grampo com torque insuficiente permite escorregamento do condutor e perda de ancoragem, enquanto jumper mal conformado gera mau contato, aquecimento e possível interrupção da continuidade elétrica, comprometendo a integridade mecânica da estrutura e o desempenho da linha. A permanência da condição mantém a conexão sujeita a afrouxamento e sobreaquecimento até a efetiva correção. {{risco_complementar}}',
  texto_acao_corretiva = 'Recomenda-se: (i) reconferir o torque dos grampos com torquímetro aferido e a conformação dos jumpers frente ao projeto, identificando as montagens fora de especificação; (ii) reapertar/reconformar as conexões não conformes aos valores de projeto, substituindo ferragens danificadas; (iii) evidenciar a correção com registro fotográfico ({{evidencia_foto_correcao}}) e planilha de conferência de torque, submetendo à reinspeção para fechamento desta RNC. Prazo: {{prazo}} dia(s) | Responsável: {{responsavel}}. {{acao_complementar}}'
where checklist_codigo = 'LT-04' and item_numero = 6;
update public.rnc_textos_base set
  gravidade_sugerida = 'Crítica — a ausência ou não conformidade da sinalização aérea em travessia/obstáculo ao voo caracteriza risco à segurança aeronáutica e demanda regularização imediata',
  texto_fundamentacao_normativa = 'Nos vãos e obstáculos assim definidos, a sinalização aérea (esferas de sinalização) deve ser instalada em quantidade, espaçamento e padrão de cores estabelecidos no projeto e na anuência aeronáutica emitida para o empreendimento. Aplicam-se as exigências da autoridade aeronáutica (anuência/DECEA) e o projeto executivo aprovado nº {{projeto_num}}, rev. {{projeto_rev}}. O critério "Esferas conforme projeto/anuência aeronáutica" constitui requisito verificável de aceitação; na ausência de certeza quanto ao número normativo específico, a exigência fundamenta-se na anuência aeronáutica do empreendimento e nas boas práticas de sinalização de obstáculos ao voo.',
  texto_risco_consequencia = 'A falta ou não conformidade das esferas de sinalização torna o cabo aéreo pouco visível a aeronaves em baixa altitude, elevando o risco de colisão com consequências catastróficas, além de descumprir a anuência aeronáutica e sujeitar o empreendimento a autuação e impedimento operacional. A permanência da condição mantém o obstáculo sem a devida sinalização até a efetiva correção. {{risco_complementar}}',
  texto_acao_corretiva = 'Recomenda-se: (i) confrontar a sinalização instalada (quantidade, espaçamento, cores e posicionamento) com o projeto e a anuência aeronáutica, identificando as pendências; (ii) instalar/regularizar as esferas de sinalização conforme o padrão aprovado nos vãos indicados; (iii) evidenciar a correção com registro fotográfico ({{evidencia_foto_correcao}}) e as-built da sinalização, submetendo à reinspeção para fechamento desta RNC. Prazo: {{prazo}} dia(s) | Responsável: {{responsavel}}. {{acao_complementar}}'
where checklist_codigo = 'LT-04' and item_numero = 7;
update public.rnc_textos_base set
  gravidade_sugerida = 'Crítica — aterramento provisório ausente ou não controlado durante o lançamento expõe a equipe a risco elétrico grave, impondo paralisação imediata',
  texto_fundamentacao_normativa = 'Durante o lançamento, os aterramentos provisórios (temporários) devem ser instalados e removidos de forma controlada e registrada, equipotencializando o cabo em relação às tensões induzidas e a energizações acidentais nos trechos de trabalho. A NR-10 (segurança em instalações e serviços em eletricidade) exige o aterramento temporário como medida de proteção coletiva antes da liberação da frente, complementada pelo procedimento de segurança da obra e pelo projeto executivo aprovado nº {{projeto_num}}, rev. {{projeto_rev}}. O critério "Instalação/remoção registrada durante o lançamento" constitui requisito verificável de liberação e encerramento da atividade.',
  texto_risco_consequencia = 'Sem aterramento provisório controlado, o cabo em lançamento acumula tensão induzida por linhas próximas ou pode ser energizado acidentalmente, expondo a equipe a choque elétrico e a arco elétrico com risco de morte, e a remoção não registrada pode deixar aterramento esquecido em trecho a energizar. A permanência da condição mantém a frente de trabalho sem a proteção coletiva exigida até a efetiva correção. {{risco_complementar}}',
  texto_acao_corretiva = 'Recomenda-se: (i) paralisar a atividade e instalar os aterramentos temporários nos pontos definidos, conferindo a equipotencialização do cabo; (ii) implantar e manter o controle documental de instalação e remoção dos aterramentos por trecho e turno, conforme a NR-10 e o procedimento da obra; (iii) evidenciar a correção com registro fotográfico ({{evidencia_foto_correcao}}) e a planilha de controle de aterramentos provisórios, submetendo à reinspeção para fechamento desta RNC. Prazo: {{prazo}} dia(s) | Responsável: {{responsavel}}. {{acao_complementar}}'
where checklist_codigo = 'LT-04' and item_numero = 8;

-- LT-05 (5 itens)
update public.rnc_textos_base set
  gravidade_sugerida = 'Maior — elevar a Crítica quando a composição divergente da cadeia comprometer a classe de isolamento, a carga mecânica de trabalho ou a compatibilidade com o tipo de estrutura (suspensão/ancoragem).',
  texto_fundamentacao_normativa = 'A cadeia de isoladores deve ser montada com a totalidade e a exata configuração de ferragens, isoladores e acessórios definidos na lista de materiais, dimensionada por tipo de estrutura (suspensão, ancoragem, terminal) segundo o projeto executivo aprovado nº {{projeto_num}}, rev. {{projeto_rev}}, o memorial de cálculo eletromecânico e a especificação técnica de fornecimento. O critério "Composição por tipo de estrutura conferida" integra o plano de inspeção da obra e constitui requisito verificável de aceitação, pois a substituição, ausência ou mistura de componentes altera o desempenho eletromecânico previsto no memorial de cálculo.',
  texto_risco_consequencia = 'Cadeia montada em desacordo com a lista de materiais pode apresentar classe de isolamento ou carga de ruptura inferior à de projeto, elevando o risco de disrupção, falha mecânica sob vento/gelo ou queda de condutor, com desligamento da linha, risco à segurança de terceiros e retrabalho de desmontagem em altura. A permanência da condição mantém a estrutura energizável fora da configuração homologada. {{risco_complementar}}',
  texto_acao_corretiva = 'Recomenda-se: (i) confrontar item a item a cadeia montada com a lista de materiais e o detalhe de montagem por tipo de estrutura, identificando componentes ausentes, trocados ou excedentes; (ii) recompor a cadeia com as ferragens, isoladores e acessórios corretos, respeitando a sequência e a orientação de projeto; (iii) evidenciar a correção com registro fotográfico ({{evidencia_foto_correcao}}) e conferência documentada da composição, submetendo à reinspeção para fechamento desta RNC. Prazo: {{prazo}} dia(s) | Responsável: {{responsavel}}. {{acao_complementar}}'
where checklist_codigo = 'LT-05' and item_numero = 1;
update public.rnc_textos_base set
  gravidade_sugerida = 'Maior — elevar a Crítica quando houver trinca, lascamento em porcelana/vidro ou dano que comprometa a estanqueidade e a rigidez dielétrica do isolador; reduzir a Menor apenas em sujidade superficial removível sem dano.',
  texto_fundamentacao_normativa = 'Os isoladores devem ser instalados íntegros e limpos, sem trincas, lascas, bolhas ou danos de manuseio e transporte, condição verificada por inspeção visual peça a peça antes e após a içagem. O requisito decorre da especificação de fornecimento e do projeto executivo aprovado nº {{projeto_num}}, rev. {{projeto_rev}}, e das boas práticas de montagem eletromecânica, uma vez que a integridade do dielétrico e a limpeza da superfície são determinantes para a suportabilidade elétrica e a linha de fuga. O critério "Sem trincas ou danos de manuseio" integra o plano de inspeção como requisito de aceitação da etapa.',
  texto_risco_consequencia = 'Isolador trincado, lascado ou contaminado reduz a linha de fuga efetiva e a rigidez dielétrica, favorecendo disrupções superficiais (flashover), correntes de fuga e perfuração do dielétrico, com risco de desligamento, dano ao condutor e ruptura mecânica da cadeia em serviço. A permanência da condição mantém ponto fraco elétrico e mecânico na estrutura. {{risco_complementar}}',
  texto_acao_corretiva = 'Recomenda-se: (i) inspecionar peça a peça a cadeia, isolando e removendo todo isolador com trinca, lasca ou dano estrutural; (ii) substituir os isoladores danificados por unidades íntegras da mesma especificação e proceder à limpeza dos que apresentem apenas sujidade superficial, conforme procedimento do fabricante; (iii) evidenciar a correção com registro fotográfico ({{evidencia_foto_correcao}}) das peças substituídas/limpas e da cadeia final, submetendo à reinspeção para fechamento desta RNC. Prazo: {{prazo}} dia(s) | Responsável: {{responsavel}}. {{acao_complementar}}'
where checklist_codigo = 'LT-05' and item_numero = 2;
update public.rnc_textos_base set
  gravidade_sugerida = 'Maior — elevar a Crítica quando a ausência ou o subtorque afetar conexões de sustentação de carga (grampos de ancoragem/suspensão) ou conexões elétricas de contato; manter Maior nos demais parafusos estruturais.',
  texto_fundamentacao_normativa = 'O torque de aperto das ferragens deve ser aplicado com ferramenta calibrada nos valores especificados pelo fabricante do componente, com registro do controle de aperto. O requisito baseia-se na especificação técnica do fornecedor das ferragens e no projeto executivo aprovado nº {{projeto_num}}, rev. {{projeto_rev}}, pois o torque correto garante a força de fixação, a pressão de contato elétrico e a resistência ao afrouxamento por vibração eólica. O critério "Conforme fabricante" integra o plano de inspeção como requisito verificável, dispensando qualquer valor arbitrado em campo.',
  texto_risco_consequencia = 'Ferragem sem torque, subtorqueada ou sobretorqueada pode afrouxar sob vibração e ciclos térmicos, gerando folga em conexões de sustentação, aumento de resistência de contato com aquecimento localizado, ou ruptura por sobreaperto, culminando em queda de condutor ou de cadeia e desligamento da linha. A permanência da condição mantém conexão instável na estrutura. {{risco_complementar}}',
  texto_acao_corretiva = 'Recomenda-se: (i) identificar as conexões sem evidência de aperto ou fora do valor especificado, consultando a tabela de torque do fabricante da ferragem; (ii) reaplicar o torque com torquímetro calibrado ao valor especificado e marcar as conexões conferidas com selo de aperto; (iii) evidenciar a correção com registro fotográfico ({{evidencia_foto_correcao}}) e planilha de controle de torque assinada, submetendo à reinspeção para fechamento desta RNC. Prazo: {{prazo}} dia(s) | Responsável: {{responsavel}}. {{acao_complementar}}'
where checklist_codigo = 'LT-05' and item_numero = 3;
update public.rnc_textos_base set
  gravidade_sugerida = 'Maior — elevar a Crítica quando a ausência ou o mau posicionamento de amortecedores/espaçadores expuser o vão à vibração eólica sustentada ou ao choque entre subcondutores, com risco de fadiga do condutor.',
  texto_fundamentacao_normativa = 'Os espaçadores e amortecedores devem ser instalados na quantidade e nas posições (distâncias ao grampo e distribuição ao longo do vão) definidas no projeto executivo aprovado nº {{projeto_num}}, rev. {{projeto_rev}}, no estudo de vibração eólica e na especificação técnica do fabricante das ferragens. O posicionamento correto controla a vibração eólica de alta frequência e mantém o espaçamento entre subcondutores do feixe. O critério "Quantidade e posição por vão conforme projeto" integra o plano de inspeção como requisito de aceitação, por ser determinante para a vida à fadiga do condutor e da amarração.',
  texto_risco_consequencia = 'Espaçadores ou amortecedores ausentes, em número insuficiente ou fora da posição de projeto deixam o vão sujeito à vibração eólica não amortecida e ao contato entre subcondutores, provocando fadiga e ruptura de fios junto aos grampos, danos ao feixe e possível queda do condutor, com desligamento e retrabalho em altura. A permanência da condição acumula dano por fadiga ao longo do tempo. {{risco_complementar}}',
  texto_acao_corretiva = 'Recomenda-se: (i) levantar por vão a quantidade e as cotas de instalação dos espaçadores e amortecedores, confrontando com o diagrama de posicionamento do projeto; (ii) instalar as peças faltantes e reposicionar as deslocadas nas distâncias especificadas, com torque de grampo conforme fabricante; (iii) evidenciar a correção com registro fotográfico ({{evidencia_foto_correcao}}) e croqui de posicionamento conferido por vão, submetendo à reinspeção para fechamento desta RNC. Prazo: {{prazo}} dia(s) | Responsável: {{responsavel}}. {{acao_complementar}}'
where checklist_codigo = 'LT-05' and item_numero = 4;
update public.rnc_textos_base set
  gravidade_sugerida = 'Menor — elevar a Maior quando a ausência de registro documentado por tramo impedir a rastreabilidade da conferência e a liberação da etapa; tratar como Observação apenas se o registro existir com pendência formal menor.',
  texto_fundamentacao_normativa = 'Cada vão (tramo) deve ter registro documentado da conferência de cadeias, ferragens e acessórios, assegurando a rastreabilidade e o encerramento da inspeção por trecho. O requisito decorre do plano de inspeção e ensaios da obra e das boas práticas de gestão da qualidade aplicáveis ao projeto executivo aprovado nº {{projeto_num}}, rev. {{projeto_rev}}, pois somente o registro por tramo comprova que a verificação abrangeu a totalidade da linha. O critério "Conferência documentada por tramo" constitui requisito de evidência objetiva da etapa.',
  texto_risco_consequencia = 'A ausência de registro por vão impede demonstrar quais tramos foram efetivamente conferidos, criando lacunas de rastreabilidade que podem deixar não conformidades ocultas sem tratamento e comprometer a liberação e o comissionamento da linha, além de fragilizar a defesa técnica em auditorias e eventuais sinistros. A permanência da condição mantém a etapa sem evidência objetiva de conformidade. {{risco_complementar}}',
  texto_acao_corretiva = 'Recomenda-se: (i) identificar os tramos sem registro de conferência e levantar as pendências documentais; (ii) realizar (ou refazer) a conferência dos vãos pendentes e formalizar o registro por tramo em planilha/relatório assinado, vinculando-o às demais evidências de inspeção; (iii) evidenciar a regularização com registro fotográfico ({{evidencia_foto_correcao}}) e os documentos de conferência por tramo, submetendo à reinspeção para fechamento desta RNC. Prazo: {{prazo}} dia(s) | Responsável: {{responsavel}}. {{acao_complementar}}'
where checklist_codigo = 'LT-05' and item_numero = 5;

-- LT-06 (4 itens)
update public.rnc_textos_base set
  gravidade_sugerida = 'Maior — elevar a Crítica quando a torre situar-se em solo de alta resistividade e o contrapeso executado não reproduzir a configuração dimensionada para aquela faixa, resultando em aterramento acima do valor de projeto.',
  texto_fundamentacao_normativa = 'A configuração dos contrapesos (número de raios, comprimento, profundidade e disposição dos cabos) deve corresponder à resistividade real do solo medida em cada torre, pois o desempenho do aterramento depende diretamente da estratificação do solo local. Aplica-se a NBR 7117 (medição da resistividade e estratificação do solo pelo método de Wenner) ao levantamento da resistividade em cada torre; a partir dela, a configuração de contrapeso por faixa de resistividade é definida pela especificação de projeto e pelas boas práticas de aterramento, conforme o projeto executivo aprovado nº {{projeto_num}}, rev. {{projeto_rev}}. O critério "Configuração por torre conforme medições de solo" integra o plano de inspeção da obra e constitui requisito verificável de aceitação da etapa.',
  texto_risco_consequencia = 'Contrapeso executado sem correspondência com a resistividade medida na torre resulta em aterramento subdimensionado, com resistência acima do projeto, elevando as sobretensões durante surtos atmosféricos e o risco de desligamentos por backflashover, bem como de tensões de passo e de toque perigosas na base da estrutura. A permanência da condição mantém o desvio ativo até a efetiva correção. {{risco_complementar}}',
  texto_acao_corretiva = 'Recomenda-se: (i) recuperar as medições de resistividade da torre e confrontá-las com as faixas de projeto, confirmando a configuração de contrapeso aplicável; (ii) complementar ou refazer o lançamento dos cabos de contrapeso (número de raios, comprimento e profundidade) conforme a configuração correta antes do reaterro definitivo; (iii) evidenciar a correção com registro fotográfico ({{evidencia_foto_correcao}}) e nova medição de resistência, submetendo à reinspeção para fechamento desta RNC. Prazo: {{prazo}} dia(s) | Responsável: {{responsavel}}. {{acao_complementar}}'
where checklist_codigo = 'LT-06' and item_numero = 1;
update public.rnc_textos_base set
  gravidade_sugerida = 'Maior — elevar a Crítica quando houver conexão comprovadamente falha (solda exotérmica porosa/incompleta ou conector mecânico frouxo) em ponto que interrompa a continuidade elétrica do sistema de aterramento.',
  texto_fundamentacao_normativa = 'As conexões entre cabos de contrapeso, hastes e o pé da torre asseguram a continuidade elétrica e mecânica do sistema de aterramento e devem estar íntegras — solda exotérmica homogênea e sem porosidade, conectores mecânicos com o torque especificado — e inspecionadas por amostragem enquanto ainda acessíveis, antes do reaterro. Na ausência de norma numérica específica de que se tenha certeza para este tipo de conexão, a exigência fundamenta-se na especificação de montagem, no projeto executivo aprovado nº {{projeto_num}}, rev. {{projeto_rev}}, e nas boas práticas consolidadas de execução de aterramento. O critério "Amostragem inspecionada antes do reaterro" integra o plano de inspeção e é requisito de aceitação, pois após o reaterro a conexão torna-se inacessível para verificação.',
  texto_risco_consequencia = 'Conexão exotérmica porosa ou conector mecânico sem aperto compromete a continuidade do aterramento e tende a agravar-se por corrosão sob o solo, podendo abrir o circuito de terra sem qualquer indício visual em superfície e exigindo reescavação para correção depois de já reaterrado, com retrabalho e atraso. {{risco_complementar}}',
  texto_acao_corretiva = 'Recomenda-se: (i) inspecionar por amostragem as conexões ainda acessíveis, verificando a homogeneidade da solda exotérmica e o torque dos conectores mecânicos conforme especificação; (ii) refazer as conexões reprovadas (nova solda exotérmica ou reaperto/substituição do conector) antes de liberar o reaterro do trecho; (iii) evidenciar a correção com registro fotográfico ({{evidencia_foto_correcao}}) das conexões íntegras, submetendo à reinspeção para fechamento desta RNC. Prazo: {{prazo}} dia(s) | Responsável: {{responsavel}}. {{acao_complementar}}'
where checklist_codigo = 'LT-06' and item_numero = 2;
update public.rnc_textos_base set
  gravidade_sugerida = 'Maior — elevar a Crítica quando a resistência de aterramento medida ultrapassar o valor máximo admissível de projeto na torre.',
  texto_fundamentacao_normativa = 'A resistência de aterramento de cada torre deve ser medida e resultar em valor igual ou inferior ao máximo definido em projeto, com o método de medição devidamente registrado. Aplicam-se a NBR 15749 (medição de resistência de aterramento e de potenciais na superfície do solo) e o projeto executivo aprovado nº {{projeto_num}}, rev. {{projeto_rev}}, que fixam o valor máximo admissível e o procedimento de aceitação. O critério "Valores ≤ projeto; método registrado" integra o plano de inspeção da obra e constitui requisito verificável de aceitação da etapa.',
  texto_risco_consequencia = 'Resistência de aterramento acima do valor de projeto eleva o potencial da torre durante descargas atmosféricas e faltas, aumentando o risco de backflashover, de desligamentos da linha e de tensões de passo e de toque perigosas junto à estrutura, além de invalidar a etapa até que nova medição comprove conformidade. {{risco_complementar}}',
  texto_acao_corretiva = 'Recomenda-se: (i) repetir a medição pela metodologia registrada (queda de potencial, conforme aplicável), confirmando o valor obtido e as condições de solo no momento do ensaio; (ii) reduzir a resistência ao valor de projeto mediante complementação do sistema (hastes adicionais, extensão de contrapeso ou tratamento de solo), conforme o caso; (iii) evidenciar a correção com registro fotográfico ({{evidencia_foto_correcao}}) e novo laudo de medição, submetendo à reinspeção para fechamento desta RNC. Prazo: {{prazo}} dia(s) | Responsável: {{responsavel}}. {{acao_complementar}}'
where checklist_codigo = 'LT-06' and item_numero = 3;
update public.rnc_textos_base set
  gravidade_sugerida = 'Menor — elevar a Maior quando a ausência ou inconsistência do registro impedir a rastreabilidade do aterramento ou o comissionamento da linha.',
  texto_fundamentacao_normativa = 'O sistema de aterramento de cada torre deve ser documentado em registro georreferenciado — planilha por torre com coordenadas, valores medidos e datas de execução e medição —, assegurando a rastreabilidade e o as-built da etapa. Trata-se de requisito de controle de registros da qualidade da obra, fundamentado no plano de inspeção e no projeto executivo aprovado nº {{projeto_num}}, rev. {{projeto_rev}}; não se cita norma numérica específica por não haver, para este requisito documental, referência aplicável de que se tenha certeza. O critério "Planilha por torre com valores e datas" constitui requisito verificável de aceitação documental da etapa.',
  texto_risco_consequencia = 'A falta do registro georreferenciado por torre impede correlacionar cada aterramento à sua localização, aos valores medidos e à data de execução, prejudicando o comissionamento, a manutenção futura e a comprovação de conformidade da etapa, podendo obrigar a remedições em campo. {{risco_complementar}}',
  texto_acao_corretiva = 'Recomenda-se: (i) consolidar a planilha por torre com coordenadas georreferenciadas, valores de resistividade/resistência e datas de execução e medição; (ii) sanar as lacunas mediante levantamento em campo das torres sem registro, vinculando os dados ao as-built da obra; (iii) evidenciar a correção com registro fotográfico ({{evidencia_foto_correcao}}) e anexar a planilha atualizada, submetendo à reinspeção para fechamento desta RNC. Prazo: {{prazo}} dia(s) | Responsável: {{responsavel}}. {{acao_complementar}}'
where checklist_codigo = 'LT-06' and item_numero = 4;

-- LT-07 (5 itens)
update public.rnc_textos_base set
  gravidade_sugerida = 'Maior — elevar a Crítica quando a vegetação ou o obstáculo reduzir a distância de segurança condutor-solo abaixo do mínimo no vão mais desfavorável, com risco iminente de descarga na energização',
  texto_fundamentacao_normativa = 'A inspeção final da faixa de servidão deve confirmar que a altura da vegetação e a presença de obstáculos preservam as distâncias de segurança entre condutores energizados e o solo, edificações e demais objetos ao longo de todo o traçado. Aplicam-se a NBR 5422 (projeto de linhas aéreas de transmissão de energia elétrica), que estabelece as distâncias mínimas de segurança, e a NR-10 (segurança em instalações e serviços em eletricidade), além do projeto executivo aprovado nº {{projeto_num}}, rev. {{projeto_rev}}, que define o perfil da faixa e as afastamentos exigidos. O critério "Altura de vegetação e obstáculos conforme critério" integra o plano de inspeção da obra e constitui requisito verificável para liberação da energização.',
  texto_risco_consequencia = 'Faixa liberada com vegetação alta ou obstáculos remanescentes reduz as distâncias de segurança do condutor energizado, elevando o risco de descarga elétrica, incêndio na faixa, desligamentos não programados e acidentes a terceiros que circulem sob a linha. A permanência da condição mantém a linha exposta a falha na primeira energização ou sob balanço dos condutores. {{risco_complementar}}',
  texto_acao_corretiva = 'Recomenda-se: (i) percorrer novamente a faixa identificando os pontos de vegetação acima do gabarito e os obstáculos remanescentes, confrontando com o perfil de projeto e as distâncias mínimas de segurança; (ii) executar a supressão/poda controlada da vegetação e a remoção ou adequação dos obstáculos, restabelecendo os afastamentos exigidos em todos os vãos; (iii) evidenciar a correção com registro fotográfico ({{evidencia_foto_correcao}}) e nova conferência das distâncias no vão mais desfavorável, submetendo à reinspeção para fechamento desta RNC. Prazo: {{prazo}} dia(s) | Responsável: {{responsavel}}. {{acao_complementar}}'
where checklist_codigo = 'LT-07' and item_numero = 1;
update public.rnc_textos_base set
  gravidade_sugerida = 'Crítica — a energização não pode ser autorizada com Punch A em aberto; manter Crítica enquanto houver pendência impeditiva não resolvida e formalmente aceita',
  texto_fundamentacao_normativa = 'O Punch A reúne as pendências impeditivas cuja resolução é condição indispensável para a energização da LT, por envolverem segurança e integridade do sistema. A exigência decorre do plano de comissionamento e da sistemática de gestão de pendências da obra, sustentada pela NR-10 (segurança em instalações e serviços em eletricidade), que veda a energização de instalação com condições impeditivas de segurança, e pelo projeto executivo aprovado nº {{projeto_num}}, rev. {{projeto_rev}}. O critério "Punch A da LT resolvido" é requisito verificável de aceitação da etapa e pré-condição de liberação para energização.',
  texto_risco_consequencia = 'Energizar a LT com itens de Punch A em aberto submete a linha a condições impeditivas não sanadas — montagens incompletas, aterramentos ou proteções pendentes — expondo pessoas e equipamentos a choque elétrico, curto-circuito e danos ao sistema, com risco de acidente grave e de indisponibilidade da linha. A permanência da condição mantém a energização bloqueada ou, se realizada, mantém o risco ativo. {{risco_complementar}}',
  texto_acao_corretiva = 'Recomenda-se: (i) listar de forma rastreável os itens de Punch A ainda em aberto, com responsável e status, confrontando com o plano de comissionamento; (ii) executar a resolução de cada pendência impeditiva e registrar a verificação técnica que comprova o atendimento, atualizando o punch list; (iii) evidenciar a correção com registro fotográfico ({{evidencia_foto_correcao}}) e o encerramento formal dos itens, submetendo à reinspeção para fechamento desta RNC. Prazo: {{prazo}} dia(s) | Responsável: {{responsavel}}. {{acao_complementar}}'
where checklist_codigo = 'LT-07' and item_numero = 2;
update public.rnc_textos_base set
  gravidade_sugerida = 'Crítica — elevação natural quando falharem verificações de fase, continuidade ou aterramento, por vedarem a energização segura; manter Crítica até novas medições conformes',
  texto_fundamentacao_normativa = 'As medições finais de comissionamento — continuidade dos condutores, resistência dos aterramentos e verificação da sequência/identificação de fases — comprovam que a LT está apta a ser energizada com segurança e corretamente conectada ao sistema. A exigência apoia-se na NR-10 (segurança em instalações e serviços em eletricidade), que condiciona a energização à verificação prévia das instalações e do aterramento, no plano de comissionamento e no projeto executivo aprovado nº {{projeto_num}}, rev. {{projeto_rev}}, que definem os valores e ensaios de aceitação. O critério "Continuidade, aterramentos e verificações de fase" é requisito verificável e não pode ser presumido.',
  texto_risco_consequencia = 'Energizar sem medições finais conformes pode ocultar aterramento com resistência acima do admissível, descontinuidade em condutor ou inversão/identificação incorreta de fase, resultando em proteção ineficaz, sobretensões, danos a equipamentos e risco de choque elétrico às equipes, além de recusa da conexão pela concessionária/ONS. A permanência da condição mantém a incerteza sobre a aptidão elétrica da linha. {{risco_complementar}}',
  texto_acao_corretiva = 'Recomenda-se: (i) reexecutar as medições de continuidade, de resistência de aterramento e a verificação de sequência e identificação de fases, comparando os resultados com os valores de aceitação do projeto e do comissionamento; (ii) tratar as não conformidades detectadas (reaperto de conexões, adequação de malhas de aterramento, correção de identificação/ligação de fases) e repetir o ensaio até conformidade; (iii) evidenciar a correção com registro fotográfico ({{evidencia_foto_correcao}}) e os relatórios de medição assinados, submetendo à reinspeção para fechamento desta RNC. Prazo: {{prazo}} dia(s) | Responsável: {{responsavel}}. {{acao_complementar}}'
where checklist_codigo = 'LT-07' and item_numero = 3;
update public.rnc_textos_base set
  gravidade_sugerida = 'Crítica — a manobra de energização não pode ocorrer sem coordenação formalizada; manter Crítica enquanto não houver aprovação documentada de horários e manobras',
  texto_fundamentacao_normativa = 'A energização de uma LT integrada à rede exige coordenação formal prévia com o ONS e/ou a concessionária, definindo janela de manobra, sequência de operações e responsabilidades, de modo a garantir a operação segura e ordenada do sistema interligado. A exigência decorre dos Procedimentos de Rede do ONS e da sistemática da concessionária de conexão, da NR-10 (segurança em instalações e serviços em eletricidade) quanto à execução de manobras, e do plano de comissionamento e projeto executivo aprovado nº {{projeto_num}}, rev. {{projeto_rev}}. O critério "ONS/concessionária com horários e manobras aprovados" é requisito verificável e pré-condição para a energização.',
  texto_risco_consequencia = 'Realizar a energização sem coordenação formalizada com ONS/concessionária pode provocar manobra em condição não autorizada, conflito com outras intervenções na rede, energização indevida de trecho, atuação de proteções sistêmicas e desligamentos, com risco à segurança das equipes e responsabilização por perturbação no sistema interligado. A permanência da condição impede a energização regular da linha. {{risco_complementar}}',
  texto_acao_corretiva = 'Recomenda-se: (i) protocolar e obter junto ao ONS/concessionária a autorização formal da energização, com data, horário, sequência de manobras e responsáveis definidos; (ii) alinhar o procedimento de manobra e as comunicações operacionais entre os centros de operação e a equipe de campo antes da energização; (iii) evidenciar a correção com registro fotográfico/documental ({{evidencia_foto_correcao}}) da autorização e do plano de manobra aprovados, submetendo à reinspeção para fechamento desta RNC. Prazo: {{prazo}} dia(s) | Responsável: {{responsavel}}. {{acao_complementar}}'
where checklist_codigo = 'LT-07' and item_numero = 4;
update public.rnc_textos_base set
  gravidade_sugerida = 'Maior — elevar a Crítica se o patrulhamento pós-energização não for realizado nas primeiras horas ou apontar anomalia (ponto quente, arco, oscilação) sem tratamento imediato',
  texto_fundamentacao_normativa = 'O patrulhamento pós-energização verifica o comportamento da linha sob tensão nas primeiras horas e dias, permitindo detectar precocemente pontos quentes, ruídos anormais, efeito corona excessivo ou peças em falha antes que evoluam para desligamento. A prática integra o plano de comissionamento e de start-up da obra e apoia-se na NR-10 (segurança em instalações e serviços em eletricidade) para a execução segura das inspeções em instalação energizada, bem como no projeto executivo aprovado nº {{projeto_num}}, rev. {{projeto_rev}}. O critério "Inspeção da linha nas primeiras horas/dias registrada" é requisito verificável de aceitação da entrega da LT.',
  texto_risco_consequencia = 'A ausência de patrulhamento registrado após a energização deixa sem monitoramento a fase crítica de estabilização da linha, permitindo que defeitos incipientes — conexões aquecidas, ferragens soltas, isoladores danificados — evoluam sem detecção até o desligamento ou falha, com perda de disponibilidade e risco a terceiros e às equipes. A permanência da condição mantém a linha sem verificação de desempenho inicial. {{risco_complementar}}',
  texto_acao_corretiva = 'Recomenda-se: (i) executar o patrulhamento da linha nas primeiras horas e dias após a energização, com inspeção termográfica e visual dos pontos críticos previstos no plano de start-up; (ii) tratar de imediato qualquer anomalia identificada (ponto quente, arco, oscilação, ferragem solta), acionando manutenção e, se necessário, manobra de desligamento; (iii) evidenciar a inspeção com registro fotográfico/termográfico ({{evidencia_foto_correcao}}) e o relatório de patrulhamento datado, submetendo à reinspeção para fechamento desta RNC. Prazo: {{prazo}} dia(s) | Responsável: {{responsavel}}. {{acao_complementar}}'
where checklist_codigo = 'LT-07' and item_numero = 5;

